INSERT INTO cpg11d_pictures VALUES (744, 3, 'userpics/10001/', 'bettyk_dirtybits01.jpg', 50874, 54775, 600, 450, 244, 20040725065618, 1076651087, 0, 'bitPimps', 0, 1, 'Dirty Bit', '[b][i]betty.k writes:[/i][/b] Dunno about you shivering northerners, but down here in ausmicro land there\'s been a bit of a trend towards off road, big wheeled, full suspension bits. it\'s the most fun i\'ve had with any of my toys so far and i can\'t recomend it enough! :)', 'betty.k dirty bits off road suspension', 'YES', '', '', '', '', 0, 3, '68.184.211.201', '68.184.211.201');
