INSERT INTO cpg11d_pictures VALUES (531, 16, 'userpics/10008/', 'motorcycle_2.jpg', 39346, 44202, 500, 350, 18, 20040725065618, 1075658785, 0, 'CaboWabo', 0, 0, 'Motorworks Motorcycle Close-Up', 'Here\'s a close up shot of one of the motorcycles. My rider is in his &quot;super speedy zoom-a-vroom&quot; position... actually he\'s always in that position - gotta be bad for the back.\r\nOverall it\'s looking pretty dooky so far.', 'motorworks motorcycle', 'YES', '', '', '', '', 0, 1, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (532, 16, 'userpics/10008/', 'motorcycle_3.jpg', 28674, 33529, 510, 300, 11, 20040725065618, 1075658977, 0, 'CaboWabo', 0, 0, 'Motorworks Motorcycle Under Shot', 'Whoa, now we really see how cheesey this thing really is...\r\ntraining wheels! I knew it! I wondered how the hell that thing was supposed to turn and stay upright. Now we know, our rider is on training wheels! I\'m surprised the product doesn\'t come with a daddy to push rider on his wittle bikey.\r\nTurns like crap because the front wheel just kind of skips on the ground. Overall - it is dooky.', 'motorworks motorcycle training wheels', 'YES', '', '', '', '', 0, 4, '68.184.211.201', '68.184.211.201');
