INSERT INTO cpg11d_pictures VALUES (799, 38, 'userpics/10008/', 'gtrr34_silver_fade_01.jpg', 15693, 20028, 300, 200, 15, 20040725065618, 1076788785, 0, 'CaboWabo', 0, 0, 'GTR R34 Skyline Fade', '', 'CaboWabo GTR R34 Skyline Fade', 'YES', '', '', '', '', 0, 4, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1899, 59, 'userpics/10009/', 'FirebirdFront.jpg', 34107, 38191, 450, 336, 8, 20040723213339, 1089353420, 9, 'Finks', 0, 0, 'Trans Am Back', 'This is a replica of my neighbors Trans Am.  Had to shave down the front end considerably and putty the hell outta the back.  He has some touch up paint from Pontiac that I will use when she is ready.  I dislike American cars, but this little mother just inspired me.', '', 'YES', '', '', '', '', 0, 1, '207.5.159.253', '207.5.159.253');
INSERT INTO cpg11d_pictures VALUES (825, 38, 'userpics/10008/', 'beetle_bitpimps_04.jpg', 39316, 42782, 400, 480, 9, 20040725065618, 1076790968, 0, 'CaboWabo', 0, 0, 'bitPimps VW Beetle', 'I added the bitPimps logo to the hood.', 'CaboWabo bitPimps VW Beetle Controller', 'YES', '', '', '', '', 0, 3, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (858, 16, 'userpics/10008/', 'preview_bling1.jpg', 21860, 29801, 400, 165, 11, 20040725065618, 1076792639, 0, 'CaboWabo', 0, 0, 'My 1st 3 Sleds', '', 'CaboWabo My 1st 3 Sleds', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (722, 33, 'userpics/10008/', 's2k_blue_fade_multi_01.jpg', 28089, 31466, 300, 375, 22, 20040725065618, 1076647109, 0, 'CaboWabo', 2000, 1, 'S-2000\'s Got The Blues', '- 2 level multi-colored fade \r\n- 1st level fade = light pearl blue &gt; metallic blue \r\n- 2nd level fade = dark metallic blue &gt; metallic black ', 'CaboWabo S-2000 Got The Blues', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (735, 33, 'userpics/10008/', 's2k_blue_2tone_04.jpg', 20649, 23514, 250, 340, 7, 20040725065618, 1076648312, 0, 'CaboWabo', 10000, 1, 'Track S-2000', 'This was one of my earlier works.', 'CaboWabo Track S-2000', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (944, 46, 'userpics/10001/', 'crazydave_race01.jpg', 28737, 35467, 450, 264, 66, 20040725065618, 1077071109, 0, 'bitPimps', 0, 0, 'Scene 1', '', '', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (692, 3, 'userpics/10001/', 'hue35_p1.jpg', 22257, 26499, 300, 203, 451, 20040725065618, 1076477199, 0, 'bitPimps', 9779, 9, 'Goin\' to the track to kick some ass...', '[b][i]hue35 writes:[/i][/b] If I were to show up at a Bit track, this is the car I\'d smoke everyone with... even Payaso! :-P', 'hue35 porsche fet kit racer springs', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (696, 31, 'userpics/10010/', 'kit1.jpg', 17136, 20728, 300, 225, 3, 20040725065618, 1076480875, 10, 'hue35', 0, 0, 'Panther clone, KIT Racer body...', 'This was the first chassis I bought, as well as my first hack job... I never really finished this idea, but I still have it in the drawer somewhere.', '', 'YES', '', '', '', '', 0, 1, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (1454, 26, 'userpics/10001/', '34_superfly_1_1.jpg', 34612, 39382, 432, 324, 27, 20040725065618, 1084842571, 0, 'bitPimps', 0, 0, 'SuperFly', '16-May-04', '', 'YES', '', '', '', '', 0, 1, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (694, 3, 'userpics/10001/', 'hue35_p3.jpg', 22860, 28859, 300, 166, 160, 20040725065618, 1076477372, 0, 'bitPimps', 0, 0, 'Goin\' to the track to kick some ass...', '[b][i]continued...[/i][/b] FETs, KIT Racer gears, 4.2 motor, finely-tuned front springs, super-low center of gravity... it\'s my favorite car to drive.', 'hue35 porsche fet kit racer springs', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (695, 3, 'userpics/10001/', 'hue35_p4.jpg', 19376, 23417, 300, 194, 171, 20040725065618, 1076477408, 0, 'bitPimps', 0, 0, 'Goin\' to the track to kick some ass...', '[b][i]continued...[/i][/b] So, instead of making it look like a brand new race car, I decided to make it look like it had a couple of ass-kicking seasons of racing under its belt.', 'hue35 porsche fet kit racer springs', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (697, 31, 'userpics/10010/', 'kit2.jpg', 15739, 18999, 300, 225, 3, 20040725065618, 1076480916, 10, 'hue35', 0, 0, '', '', '', 'YES', '', '', '', '', 0, 6, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (698, 31, 'userpics/10010/', 'kit3.jpg', 20880, 25287, 300, 225, 6, 20040725065618, 1076480958, 10, 'hue35', 0, 0, '', '', '', 'YES', '', '', '', '', 0, 8, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (699, 31, 'userpics/10010/', 'kit4.jpg', 32663, 38140, 300, 225, 9, 20040725065618, 1076480999, 10, 'hue35', 0, 0, '', '', '', 'YES', '', '', '', '', 0, 3, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (700, 31, 'userpics/10010/', 'nsx.jpg', 22366, 25707, 400, 300, 6, 20040725065618, 1076481302, 10, 'hue35', 0, 0, 'Le Mans NSX...', 'This was my first TOMY car... Auto Modellista 2-speed chassis with the Mobil1 NSX body. I couldn\'t resist making it look like it had been driven hard. SuperFly\'s is still new lookin\'... still one of our best pairs of cars we race.', '', 'YES', '', '', '', '', 0, 2, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (701, 31, 'userpics/10010/', 'rx7.jpg', 27931, 31940, 400, 300, 4, 20040725065618, 1076481474, 10, 'hue35', 0, 0, 'My first dual cell car...', 'A MicroSizers Pro with some vinyl stripes. For a long time, this was my best car... it\'s still right up there. Dual-celled cars kick ass!', '', 'YES', '', '', '', '', 0, 0, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (739, 33, 'userpics/10008/', 's2k_blue_fade_04.jpg', 32539, 36765, 400, 350, 6, 20040725065618, 1076648762, 0, 'CaboWabo', 10000, 1, 'Daily Special - Track Car 2.0', 'Coat of dark metallic blue.', 'CaboWabo Daily Special - Track Car 2.0', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (981, 42, 'userpics/10013/', 'DSC00123.jpg', 47697, 51192, 800, 600, 19, 20040725065618, 1077260061, 13, 'YAGBOLS', 0, 0, 'DATSUN 510', '', '', 'YES', '', '', '', '', 0, 3, '203.131.103.167', '203.131.103.167');
INSERT INTO cpg11d_pictures VALUES (703, 31, 'userpics/10010/', 'z350.jpg', 23694, 27551, 400, 275, 2, 20040725065618, 1076482353, 10, 'hue35', 0, 0, 'My second dual cell...', 'Also a MicroSizers Pro. This was a cleaner job on the internal dual cell, and this car features my first &quot;HogAxle&quot;... epoxy that axle right in place. Orange gears and dual cells make for a fun amount of torque. This car literally whips around the track.', '', 'YES', '', '', '', '', 0, 1, '165.121.37.106', '165.121.37.106');
INSERT INTO cpg11d_pictures VALUES (704, 3, 'userpics/10001/', 'crazydave_beetle_vdm01.jpg', 23348, 26901, 400, 322, 101, 20040723213339, 1076620744, 0, 'bitPimps', 0, 0, 'Sick Green Flames', '[b][i]crazydave writes:[/i][/b] I was doing some mods for VDM, and he\'s hooking me up. So I wanted to give him a little something extra. So I offered to flame out his LXX Beetle. He wasn\'t saying no.\r\n\r\nSo here\'s you car now VDM. :)', 'crazydave beetle flames', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (705, 3, 'userpics/10001/', 'crazydave_beetle_vdm02.jpg', 16981, 21349, 400, 246, 114, 20040725065618, 1076620803, 0, 'bitPimps', 0, 0, 'Sick Green Flames', '[b][i]continued...[/i][/b] I liked the sick green the car came in, but alot of the LXX paint mask were put on crooked. I thought I could keep the green, and clean up the areas where the paint mask had been crooked. I faded some Aqua in the front, and layed Charcoal over the rest.', 'crazydave beetle flames', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (706, 3, 'userpics/10001/', 'crazydave_beetle_vdm03.jpg', 16852, 20566, 400, 265, 93, 20040725065618, 1076620848, 0, 'bitPimps', 10000, 1, 'Sick Green Flames', '[b][i]continued...[/i][/b] Pics do not do this job justice. The flash makes the Aqua blend into the green to much, and you can\'t really see how smooth the fade really looks. This shade of charcoal always looks black in pics, but really it\'s a dark metallic grey. I would have spent half the day trying to get the pictures just right, but in this case I knew VDM was going to be able vouch for it when he got it.\r\n\r\nSo here it is...Hope you like it VDM. I\'m proud of it.', 'crazydave beetle flames', 'YES', '', '', '', '', 0, 6, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (707, 32, 'userpics/10011/', 'contest1.JPG', 42610, 91018, 673, 505, 14, 20040725065618, 1076624165, 11, 'ph2t', 0, 0, 'KnightRider', 'Still my favorite bit to date.  2nd place in the Bitpimps Twisted Plastic comp.', '', 'YES', '', '', '', '', 0, 7, '203.26.37.35', '203.26.37.35');
INSERT INTO cpg11d_pictures VALUES (708, 32, 'userpics/10011/', 'contest3.JPG', 26372, 30167, 542, 417, 8, 20040723213339, 1076624220, 11, 'ph2t', 0, 0, 'KnightRider2', '', '', 'YES', '', '', '', '', 0, 1, '203.26.37.35', '203.26.37.35');
INSERT INTO cpg11d_pictures VALUES (709, 32, 'userpics/10011/', 'detail_1.JPG', 35342, 38457, 577, 455, 14, 20040725065618, 1076624305, 11, 'ph2t', 0, 0, '350z', 'First putty mod.  I filled the back window in!   Nice looking car with a darker undercoat to bring out the panel lines..', '', 'YES', '', '', '', '', 0, 3, '203.26.37.35', '203.26.37.35');
