INSERT INTO cpg11d_pictures VALUES (880, 38, 'userpics/10008/', 'jota_darkblue_01.jpg', 46087, 49415, 500, 550, 31, 20040725065618, 1076882552, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'After a few months of not modding, I decided to come back with this Lamborghini Jota.', '', 'YES', '', '', '', '', 0, 4, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (881, 38, 'userpics/10008/', 'jota_darkblue_02.jpg', 43504, 47125, 500, 500, 40, 20040725065618, 1076882595, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'I took it easy and decided I would just do some body modding and not any kind of real chopping.', '', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (882, 38, 'userpics/10008/', 'jota_darkblue_03.jpg', 43413, 46753, 500, 490, 26, 20040725065618, 1076882641, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'I decided that I wanted my Jota to look a little more sleek, smooth, and clean as compared to the original.', '', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (883, 38, 'userpics/10008/', 'jota_darkblue_04.jpg', 51017, 54730, 500, 430, 177, 20040725111224, 1076882759, 0, 'CaboWabo', 9111, 9, 'Midnight Jota Jamboree', 'I ended up filling in all the air vents, 6 in total. 2 on the hood, one just past the front wheel well on each side, and another just past the rear wheel well on each side.', '', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (884, 38, 'userpics/10008/', 'jota_darkblue_05.jpg', 44335, 47644, 500, 450, 28, 20040725065618, 1076882865, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'The hood had some sort of filter sticking out and the wing in the rear that sat high on the rear window ended up getting the chop as well.', '', 'YES', '', '', '', '', 0, 3, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (885, 38, 'userpics/10008/', 'jota_darkblue_06.jpg', 51623, 55060, 500, 470, 29, 20040723213333, 1076882921, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'After filling in, sanding and smoothing - I decided on a nice dark metallic blue for the color.', '', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (886, 38, 'userpics/10008/', 'jota_darkblue_07.jpg', 42931, 46801, 500, 400, 32, 20040725065618, 1076883019, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'The Jota came with a Super-Bit chassis, so I bought a Super-Bit Pullback and transferred the pullback wheels to the chassis.', '', 'YES', '', '', '', '', 0, 4, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (887, 38, 'userpics/10008/', 'jota_darkblue_08.jpg', 43484, 47686, 500, 390, 30, 20040725065618, 1076883073, 0, 'CaboWabo', 10000, 1, 'Midnight Jota Jamboree', 'Now this baby is ready for some flossin in da hood!', '', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
