INSERT INTO cpg11d_pictures VALUES (889, 39, 'userpics/10007/', 'sscam2.jpg', 14421, 17539, 400, 274, 18, 20040725065618, 1076890281, 7, 'crazydave', 0, 0, 'The Other SS Camaro', 'When I got the Camaro SS body set, I had to something with the other body, so it\'s on a dual cell FET modded Zip Zap w/ a Dub City wheel mod done.', '', 'YES', '', '', '', '', 0, 4, '68.3.175.186', '68.3.175.186');
