INSERT INTO cpg11d_pictures VALUES (911, 35, 'userpics/10005/', 'GoldenRod.jpg', 101858, 179997, 640, 480, 75, 20040725065618, 1076902917, 5, 'DarkTari', 10000, 1, 'Azz Shot', 'Loaded with Mods. Full custom ground effects w/ vented air dam, L88 hood scoop, custom tail lights, fully detailed interior, convertable toneau cover, quad aluminum exhaust. Not lowered at all. ', '', 'YES', '', '', '', '', 0, 4, '67.27.78.72', '67.27.78.72');
INSERT INTO cpg11d_pictures VALUES (912, 35, 'userpics/10005/', 'MintCond1.jpg', 92758, 164290, 640, 480, 109, 20040725065618, 1076903196, 5, 'DarkTari', 8667, 3, 'Herbie II on Steroids', 'The detailing came out so damn good on this one.....', '', 'YES', '', '', '', '', 0, 4, '67.27.78.72', '67.27.78.72');
INSERT INTO cpg11d_pictures VALUES (913, 35, 'userpics/10005/', 'MintCond2.jpg', 103170, 177673, 640, 480, 93, 20040725065618, 1076903495, 5, 'DarkTari', 10000, 1, 'Azz Shot', 'Full custom ground effects w/ whale tail, front tab lowered, Muscle Machine caps on ZipZap hubs, Dual oval aluminum exhaust.', '', 'YES', '', '', '', '', 0, 6, '67.27.78.72', '67.27.78.72');
INSERT INTO cpg11d_pictures VALUES (914, 35, 'userpics/10005/', 'F360Modena 01.jpg', 78628, 140253, 640, 480, 280, 20040725065618, 1076904020, 5, 'DarkTari', 9400, 10, 'Funky Cold Modena !', 'I wanted this body so bad when I 1st saw it, hated it when I got some, decided to do a lil sumtin and came up with this.............\r\nI LUV it now !', '', 'YES', '', '', '', '', 0, 5, '67.27.78.72', '67.27.78.72');
INSERT INTO cpg11d_pictures VALUES (915, 35, 'userpics/10005/', 'F360Modena.jpg', 102561, 181688, 640, 480, 108, 20040725065618, 1076904506, 5, 'DarkTari', 10000, 2, 'Azz Shot', 'The Pics speak for themselves !  My favorite one is here:http://bitpimps.lixlink.com/pages/phpGallery/displayimage.php?album=14&pos=6 in the BitPimp Wall Paper Gallery!', '', 'YES', '', '', '', '', 0, 5, '67.27.78.72', '67.27.78.72');
INSERT INTO cpg11d_pictures VALUES (916, 35, 'userpics/10005/', 'Maserati3.JPG', 105735, 186061, 640, 480, 162, 20040725093137, 1076904954, 5, 'DarkTari', 10000, 1, 'Another BigLots Micro....', 'Here\'s my $6.99 BigLots Micro Speed car.  Decided to give it an identity.  Full Custom Ground effects, front tab lowered, quad aluminum exhaust.', '', 'YES', '', '', '', '', 0, 1, '67.27.78.72', '67.27.78.72');
