INSERT INTO cpg11d_pictures VALUES (1107, 56, 'userpics/10028/', 'Track2~0.jpg', 50742, 55254, 400, 225, 19, 20040725065618, 1080150173, 28, 'ripper7777777', 0, 0, 'Battling Skylines', 'This is a pic of 2 Epoch Skylines I did for a customer.  It gives a good size compatison of the details on the track.', '', 'YES', '', '', '', '', 0, 3, '24.242.228.211', '24.242.228.211');
