INSERT INTO cpg11d_pictures VALUES (1105, 56, 'userpics/10028/', 'Track1.jpg', 66117, 70167, 400, 271, 18, 20040725065618, 1080150032, 28, 'ripper7777777', 0, 0, 'Micro RC Grand Raceway 2', 'This Track replaced the Original Micro RC Grand Raceway. When I stepped up into the epoch realm I needed a little more space. This track is also great for dual cell ZZ\'s and Bits, plenty of room to test the throttle. The track itself folds back up on to the table and the Overall Dims are 8\'x7\' and the average lane width is 12&quot;. I hated destroying the other track but once this one was complete, I quickly forgot the old track.', '', 'YES', '', '', '', '', 0, 5, '24.242.228.211', '24.242.228.211');
INSERT INTO cpg11d_pictures VALUES (1110, 56, 'userpics/10028/', 'Track4.jpg', 57177, 60518, 400, 300, 12, 20040725065618, 1080151196, 28, 'ripper7777777', 0, 0, 'Just another pic', 'One last Detail shot.\r\nYou can see more pics at my Home page - http://home.houston.rr.com/extremedesigns/', '', 'YES', '', '', '', '', 0, 1, '24.242.228.211', '24.242.228.211');
INSERT INTO cpg11d_pictures VALUES (1113, 57, 'userpics/10019/', '3.jpg', 33356, 42334, 400, 189, 6, 20040725065618, 1080273318, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 3', '&quot;I was informed that the notorious &quot;bitPimps&quot; syndicate was attempting to overthrow the state of Pimpafornia by massing at the state assembly building.&quot;\r\n\r\n&quot;I got to flyin\' in my Air Force One immediately, to assist the governor of Pimpafornia, Aahnold SportsnJager, at the assembly.&quot;', '', 'YES', '', '', '', '', 0, 0, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1114, 57, 'userpics/10019/', '4.jpg', 13827, 18353, 400, 174, 4, 20040723213339, 1080273379, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 4', '&quot;Ya, deez peemps vill not be staging any coup in de state of Peempaahfohnia vile Ah\'m de guuvuhnaaah&quot;( cheesy Austrian accent) \r\n\r\n&quot;We will now send in the P.C.P.D to attempt to negotiate with the ringleaders&quot;.', '', 'YES', '', '', '', '', 0, 7, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1115, 57, 'userpics/10019/', '5.jpg', 43083, 49044, 400, 300, 6, 20040725065618, 1080273653, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 5', '&quot;Um, fellas, uh, you think you can disperse immediately? The president and the governor are trying to avoid a confrontation... plus they\'re punks...&quot; \r\n\r\n&quot;Oh hell no! Tell those fools they gotta come tell us to our face!&quot;\r\n\r\n&quot;Ok, fellas... calm down... Can I offer you one of these here tasty donuts?&quot;', '', 'YES', '', '', '', '', 0, 1, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1116, 57, 'userpics/10019/', '7.jpg', 13827, 18353, 400, 174, 4, 20040725065618, 1080273735, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 7', '&quot;So, as you can see, or not, due to the mysterious disappearance of pic #6(dammit!), that governor SportsnJager and myself were accosted by those treacherous thugs.&quot;', '', 'YES', '', '', '', '', 0, 6, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1117, 57, 'userpics/10019/', '8.jpg', 44333, 50208, 400, 300, 6, 20040725065618, 1080273760, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 8', '&quot;Ya, vee deed naaht know zat zey haaahd a taaaaahnk!&quot; \r\n(cheesy Austrian accent again)', '', 'YES', '', '', '', '', 0, 6, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1118, 57, 'userpics/10019/', '9.jpg', 29191, 37622, 400, 188, 8, 20040725065618, 1080273797, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 9', '&quot;So, here are the new leaders of the free world, the notorious bitPimps&quot;', '', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
