INSERT INTO cpg11d_pictures VALUES (1138, 60, 'userpics/10019/', '03.jpg', 54041, 57597, 500, 450, 6, 20040725065618, 1081132364, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 3', 'They decide to catch a Steeler game first and do a little drinkin\'.....', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1139, 60, 'userpics/10019/', '04.jpg', 53142, 56562, 490, 500, 5, 20040725065618, 1081132396, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 4', 'While at the game they meet up with Phat Boy, the biggest slum lord in town. He wants to talk some business out west that could set them up for the good life.', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1140, 60, 'userpics/10019/', '05.jpg', 52395, 55825, 500, 430, 6, 20040725065618, 1081132446, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 5', 'Phat Boy ends up throwin\' out the idea out straight robbin\' the Steel Reserve Bank. \r\n\r\nMr. Green and Sam are thinkin\' this pimp is havin\' some Delerious Tremens in the head.', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1141, 60, 'userpics/10019/', '06.jpg', 59877, 65015, 500, 360, 4, 20040725065618, 1081132476, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 6', 'They leave the game and head out on the road. They get out in the midwest and meet up with Pimp Gotti at the Crazy Horse Saloon. Pimp Gotti heard about the big action going down and wants in on it. Being that its such a big score, they decide they need the help out west and tell Pimp Gotti about the score.', '', 'YES', '', '', '', '', 0, 0, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1142, 60, 'userpics/10019/', '07.jpg', 51452, 55922, 500, 380, 6, 20040725065618, 1081132508, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 7', 'Mr. Green and Sam get out west and stop at that big hole in the ground for some R&R.', '', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1143, 60, 'userpics/10019/', '08.jpg', 78086, 83550, 500, 400, 6, 20040725065618, 1081132547, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 8', 'While there the clock hits 4:20, so they decide to go chill for a minute and enjoy the veiw from Old Mount Bottle Cap. \r\n\r\nAfter they catch they\'re breath down off the mountian, they head Back to the Hotel to chill with some fine pimpettes for a good nights...... \r\n\r\nThe next day is the job. \r\n\r\nMr. Green and Sam pull of the big score with stealth like presision and head back east to Pimp Gotti\'s place down in Mississippi.', '', 'YES', '', '', '', '', 0, 0, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1144, 60, 'userpics/10019/', '09.jpg', 45303, 50027, 500, 330, 3, 20040725065618, 1081132587, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 9', 'Hang out at the Bankers Club for a few to square up with Pimp Gotti and then off to the good life. Pimp Gotti can\'t beleive how quick they pulled the job off, and didn\'t get caught. \r\n\r\nMr. Green and Sam reply with, &quot;Never talk about Pimp Club, Just live it, and enjoy it and things will happen. If they don\'t happen, you wack\'em!!&quot;', '', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1145, 60, 'userpics/10019/', '10.jpg', 41593, 46435, 500, 320, 6, 20040725065618, 1081132613, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 10', '', '', 'YES', '', '', '', '', 0, 6, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1146, 60, 'userpics/10019/', '11.jpg', 38509, 47105, 500, 200, 5, 20040725065618, 1081132670, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 11', 'Now that they have they\'re money and still have they\'re freedom and lives, they can dream about (L to R), being healthy and fit, settling down with a good woman and forget about getting locked up and exercise the demons from their minds.', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
