INSERT INTO cpg11d_pictures VALUES (1156, 55, 'userpics/10028/', 'shineyGTR.jpg', 40461, 44693, 400, 330, 29, 20040725065618, 1081284777, 28, 'ripper7777777', 10000, 2, 'GTR', 'This was my first paint job on a bit, it was also my favorite chassis, I had it set-up just perfect for my bit track it was an awesome little car untill one sad afternoon when I forgot to shut off the charger and melted the chassis.  The body survived fine but the spirit of the car died.', '', 'YES', '', '', '', '', 0, 1, '24.242.228.211', '24.242.228.211');
