INSERT INTO cpg11d_pictures VALUES (1190, 3, 'userpics/10001/', 'ripper7_dragster_2.jpg', 35603, 39583, 400, 297, 135, 20040723213333, 1081902958, 0, 'bitPimps', 0, 0, 'Mustang Funny Car', '[b][i]continued...[/i][/b] After building the dragster it looked kinda funny sitting next to ordinary bits so I decided it needed a counterpart for it, so what better than a Funny Car. It sports a stretched bit chassis, a stretched ZZ mustang body, and uses the same 4-cell battery pack. \r\nripper7777777 - www.ripper7racing.com', 'ripper7777777 Dragster Mustang Funny Car', 'YES', '', '', '', '', 0, 6, '68.184.211.201', '68.184.211.201');
