INSERT INTO cpg11d_pictures VALUES (1179, 26, 'userpics/10001/', '29_geisem_2.jpg', 37645, 41173, 600, 450, 74, 20040725065618, 1081742370, 0, 'bitPimps', 0, 0, 'Geisem', '11-Apr-04', '', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1180, 66, 'userpics/10019/', '01~0.jpg', 100445, 106407, 600, 450, 10, 20040725065618, 1081743730, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 1', 'Well i just got the call from ph2t, he\'s coming over at lunchtime, i just gotta go pick him up from the train station. so let\'s go see a little bit of australia on the way!', '', 'YES', '', '', '', '', 0, 6, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1181, 66, 'userpics/10019/', '02~0.jpg', 79560, 84654, 600, 450, 10, 20040725065618, 1081743760, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 2', 'Crikey!! here\'s a little laser shooting ant!! lucky for me he\'s just a little feller or i\'d never make it to the car! his laser\'s really starting to hurt now and his mother could be close so we better get outta here!', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1182, 66, 'userpics/10019/', '03~0.jpg', 65751, 70827, 600, 450, 9, 20040725065618, 1081743791, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 3', 'Whooaaaa!! didn\'t see this little beauty! this is an eastern bullcrap snake (slipperius latexus). good thing for me he\'s pretty slow and only a baby. this is their way of familiarising themselves with their surroundings! i can feel his fangs piercing my lungs right now!', '', 'YES', '', '', '', '', 0, 3, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1183, 66, 'userpics/10019/', '04~0.jpg', 48127, 52489, 600, 450, 9, 20040725065618, 1081743826, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 4', 'Phew!! all that cuddlin gave me a bloody ripper of an apetite! early explorers perished in this harsh outback climate, cos they didn\'t know how to survive from the natural environment. through years of croc chasing i\'ve come to learn to recognise the signs that there\'s some good eatin\' nearby..............', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1184, 66, 'userpics/10019/', '05~0.jpg', 88132, 93169, 600, 450, 9, 20040725065618, 1081743867, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 5', '.....and here we go, good ol aussie tucker!! i hope they still got those grouse dingo nuggets!', '', 'YES', '', '', '', '', 0, 5, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1185, 66, 'userpics/10019/', '06~0.jpg', 76458, 80921, 600, 450, 8, 20040725065618, 1081743900, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 6', 'Introduced species are a real problem in our country, and there\'s none worse than the dreaded arctic feral cat (felinus stupidicus). AAAGH! CRIKEY!!! he\'s got us! quick bruce, punch it while he\'s looking the other way!!', '', 'YES', '', '', '', '', 0, 4, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1186, 66, 'userpics/10019/', '07~0.jpg', 87621, 93871, 600, 450, 7, 20040725065618, 1081743934, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 7', 'Have a look at this little beauty! it\'s a speckled fart sucker (arachnogaseus vacumicus) i\'m not going to get too close because once they attach themselves to you they drive their foot long fangs into ya abdomen and drain your gases and inflate themselves enough to float, using the winds to carry them to more fertile feeding grounds!', '', 'YES', '', '', '', '', 0, 2, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1187, 66, 'userpics/10019/', '08~0.jpg', 71819, 76790, 600, 450, 11, 20040725065618, 1081743969, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 8', 'Struth! finally at the station. there\'s ph2t in the snacks car and hey look! there\'s bruce on his vespa! azzitgarn bruce!?', '', 'YES', '', '', '', '', 0, 8, '68.184.211.201', '68.184.211.201');
INSERT INTO cpg11d_pictures VALUES (1188, 66, 'userpics/10019/', '09~0.jpg', 74444, 79556, 600, 450, 8, 20040725065618, 1081743999, 19, 'bitPimps Picture Stories', 0, 0, 'Scene 9', 'Well after all that trekking we decide to head to the local pub for just the one (i\'m driving). and after that we\'re gonna head on back to the ol\' homestead for a little bit of bit racin\' and some gardenin\'! hope you enjoyed me grouse adventures as much as i did!! seeyaslater!', '', 'YES', '', '', '', '', 0, 0, '68.184.211.201', '68.184.211.201');
