INSERT INTO cpg11d_pictures VALUES (1219, 69, 'userpics/10019/', 'mm_02.jpg', 36399, 39161, 333, 500, 18, 20040723213339, 1082696230, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 2', 'you can see the club owners chillin in their usual lounge!', '', 'YES', '', '', '', '', 0, 2, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1220, 69, 'userpics/10019/', 'mm_03.jpg', 25987, 29645, 500, 333, 16, 20040725065618, 1082696259, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 3', 'checkin to make sure nobody acts a fool!', '', 'YES', '', '', '', '', 0, 6, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1221, 69, 'userpics/10019/', 'mm_04.jpg', 46169, 52203, 500, 333, 16, 20040725065618, 1082696289, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 4', 'I turned my camera on just in time to see a member of the bitPimps get knocked down.', '', 'YES', '', '', '', '', 0, 1, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1222, 69, 'userpics/10019/', 'mm_05.jpg', 46589, 51603, 500, 333, 17, 20040725065618, 1082696322, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 5', 'before I knew it, midget_man(short one) and his accomplice, DarkTari had gotten upset. A crowd formed a circle around them.', '', 'YES', '', '', '', '', 0, 3, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1223, 69, 'userpics/10019/', 'mm_06.jpg', 46324, 52549, 500, 333, 17, 20040725065618, 1082696367, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 6', 'I heard the little one, midget_man saying, &quot;What, you want some of this shit, biatch!!?? I\'ll work you, dogg!!&quot;', '', 'YES', '', '', '', '', 0, 2, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1224, 69, 'userpics/10019/', 'mm_07.jpg', 45765, 51996, 500, 333, 14, 20040725065618, 1082696391, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 7', 'I kept snapping photos, as midget_man bumrushed the man, tackling him to the ground. ', '', 'YES', '', '', '', '', 0, 1, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1225, 69, 'userpics/10019/', 'mm_08.jpg', 41847, 47410, 500, 333, 13, 20040725065618, 1082696419, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 8', 'as he was on the ground, the pair of gangsters continued &quot;whooping ass&quot;, as the bitPimps call it. The kicked and punched him as he lay helplessly on the ground. They even let their dog get in on the action.', '', 'YES', '', '', '', '', 0, 2, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1226, 69, 'userpics/10019/', 'mm_09.jpg', 28978, 32201, 500, 333, 15, 20040725065618, 1082696451, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 9', 'all of the sudden, the club owners came out of nowhere and knocked me to the ground, knocking the lens off my camera. They kicked the two men and their dog out, telling them never to come back. I fixed my camera in time to see them getting told never to return.', '', 'YES', '', '', '', '', 0, 4, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1227, 69, 'userpics/10019/', 'mm_10.jpg', 19212, 22750, 500, 333, 26, 20040725065618, 1082696485, 19, 'bitPimps Picture Stories', 10000, 1, 'Scene 10', 'I was able to get one more picture, as the pimps got in their lowrider and screamed off. I was told later by the club owner that the man survived the attack, but had many cuts and bruises.', '', 'YES', '', '', '', '', 0, 8, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1229, 83, 'userpics/10012/', 'skylinepbshell.JPG', 219173, 281643, 1280, 960, 12, 20040725065618, 1082733776, 12, 'betty.k', 0, 0, '', '', '', 'YES', '', '', '', '', 0, 3, '210.50.30.20', '210.50.44.149');
INSERT INTO cpg11d_pictures VALUES (1230, 64, 'userpics/10031/', 'DCP_3729.JPG', 19945, 20480, 500, 333, 16, 20040725065618, 1082749986, 31, 'midget_man1387', 0, 0, 'project: keepin it low and slow', 'Here is my latest project. It is a lowrider that I had to move the idler gear because it was so low.', 'lowrider bB slammed', 'YES', '', '', '', '', 0, 8, '66.132.6.174', '66.132.6.174');
INSERT INTO cpg11d_pictures VALUES (1514, 64, 'userpics/10031/', 'DCP_0027.jpg', 14911, 18578, 400, 266, 8, 20040725065618, 1086367925, 31, 'midget_man1387', 0, 0, 'contest celica', 'this is a celica that I made for this contest.... I\'ve been working on it for months, but when the contest rolled around I kicked it into high gear and told myself i needed to work on this. I\'m very please with the painting... The lines on the side are hand masked, then gone over, actually dotted with black paint. that gave it the kind of &quot;ripped effect.&quot;', '', 'YES', '', '', '', '', 0, 5, '67.129.200.195', '67.129.200.195');
