INSERT INTO cpg11d_pictures VALUES (1563, 3, 'userpics/10001/', 'payaso_cuda_1.jpg', 18791, 22712, 600, 450, 61, 20040725065618, 1087429252, 0, 'bitPimps', 0, 0, 'Evil Cuda', '[b][i]payaso writes:[/i][/b] I thought I\'d give the Hemi a little touch up, so I pulled the hubs out, and stripped em back to bare metal. i still wasn\'t happy with em, so I took a jewelers cloth, and hand polished em to a mirror finish. (still haven\'t figured out how to capture the bling on film).', 'payaso hemi cuda', 'YES', '', '', '', '', 0, 8, '24.207.244.0', '24.207.244.0');
INSERT INTO cpg11d_pictures VALUES (1564, 3, 'userpics/10001/', 'payaso_cuda_2.jpg', 15879, 19519, 600, 450, 40, 20040723213339, 1087429270, 0, 'bitPimps', 0, 0, 'Evil Cuda', '[b][i]continued...[/i][/b] I put some lights on it, and dropped it as low as it can go. It still needs a clear coat, but this it it after the slight alteration.', 'payaso hemi cuda', 'YES', '', '', '', '', 0, 4, '24.207.244.0', '24.207.244.0');
