INSERT INTO cpg11d_pictures VALUES (1886, 101, 'userpics/10038/', 'my dual cell accord lives!.jpg', 10015, 12700, 260, 195, 4, 20040725065618, 1089350444, 38, 'micro_man', 0, 0, 'my first dual cell car ,moded a bit', 'this is my first dual cell car , with dif batts a faster pink clone motor ( i love those)  a difrent body and a guitar string antena . it also has anti flip wings and the pice of plastic glued on the rear end mod to hold the gears in . ', '', 'YES', '', '', '', '', 0, 4, '67.217.10.199', '67.217.10.199');
INSERT INTO cpg11d_pictures VALUES (1887, 101, 'userpics/10038/', 'my score form mekinhux.jpg', 29798, 34248, 400, 300, 6, 20040725065618, 1089350651, 38, 'micro_man', 0, 0, 'stuff', 'a trade with mekinhux , look at all the goodies lol . he got a zz se and some parts , hope hes as happy as me . ', '', 'YES', '', '', '', '', 0, 6, '67.217.10.199', '67.217.10.199');
INSERT INTO cpg11d_pictures VALUES (1888, 101, 'userpics/10038/', 'my sp.jpg', 7456, 11496, 240, 180, 6, 20040725065618, 1089351034, 38, 'micro_man', 0, 0, 'ooooo it glows', 'another shot of my Super Prefection . this car is one of my favorites ,  just needs a faster motor . all it has is a prefection 2.2 , smooth , but slow. ', '', 'YES', '', '', '', '', 0, 1, '67.217.10.199', '67.217.10.199');
