INSERT INTO cpg11d_pictures VALUES (2154, 59, 'userpics/10009/', 'BitBoat-009.jpg', 23909, 27392, 450, 317, 2, 20040725065618, 1090635771, 9, 'Finks', 0, 0, 'Windows 2004', 'Repainted her and used fishing line for the guardrail.  Bye bye frays and pink hull', '', 'YES', '', '', '', '', 0, 1, '207.5.159.253', '207.5.159.253');
INSERT INTO cpg11d_pictures VALUES (2130, 125, 'userpics/10044/', 'DSC00530.jpg', 19836, 43448, 640, 480, 2, 20040724104017, 1090489535, 44, 'mekinhux', 0, 0, '350z with pullback wheel mod', 'This is the only body I can run this chassis without any sanding or modding. The front wheel weels of the 350z are really large and it looks killer with this old style rims.', '', 'YES', '', '', '', '', 0, 2, '193.136.33.207', '193.136.33.207');
INSERT INTO cpg11d_pictures VALUES (2131, 125, 'userpics/10044/', 'DSC00533.jpg', 18751, 40990, 640, 480, 1, 20040725065618, 1090489563, 44, 'mekinhux', 0, 0, 'chassis with pullback wheel mod', 'Old style pullback wheels. I\'ve used the front wheels from two pullbacks, since I couldn\'t get the bigger ones to fit the rear axle properly.', '', 'YES', '', '', '', '', 0, 2, '193.136.33.207', '193.136.33.207');
INSERT INTO cpg11d_pictures VALUES (2132, 123, 'userpics/10044/', 'DSC00573.jpg', 21374, 46662, 640, 480, 2, 20040724120520, 1090489722, 44, 'mekinhux', 0, 0, 'toyota bb open deck', 'Still haven\'t figured out which color I\'ll be painting this one, but it\'s a very smooth body.', '', 'YES', '', '', '', '', 0, 3, '193.136.33.207', '193.136.33.207');
