INSERT INTO cpg11d_pictures VALUES (2136, 123, 'userpics/10044/', 'DSC00319.jpg', 23424, 51239, 640, 480, 3, 20040725065618, 1090489820, 44, 'mekinhux', 0, 0, 'mazda rx-7', 'You might have noticed the crack at the front wheel wells. I fixed it with super glue, sanded it and put primer on it. But it still needs more sanding. Also filled up the rear wing holes with super glue and it\'s looking good.', '', 'YES', '', '', '', '', 0, 2, '193.136.33.207', '193.136.33.207');
